package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// countReq represents the count request message
type countReq struct {
	MsgID   int      `json:"msg_id"`
	Visitors int      `json:"visitors"`
}

// countRes represents the counted response message
type countRes struct {
	InReplyTo int `json:"in_reply_to"`
}

// totalReq represents the total request message
type totalReq struct {
	MsgID int `json:"msg_id"`
}

// totalRes represents the total_is response message
type totalRes struct {
	InReplyTo     int  `json:"in_reply_to"`
	VisitorsSoFar int  `json:"visitors_so_far"`
}

func main() {
	node := go.NewNode(0)

	node.Handle("count", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req countReq
		if err := json.Unmarshal(in, &req); err != nil {
			return nil, fmt.Errorf("unmarshal failed: %w", err)
		}

		// Read current total from KV store
		var readers int64
		ctx = go.WithLogger(ctx, log.Default())
		if readers, err = node.RW(ctx, "counter", 0); err != nil {
			return nil, fmt.Errorf("read counter failed: %w", err)
		}

		// Increment the counter using CompareAndSwap for atomic update
		newVal := int64(readers + int64(req.Visitors))
		ctx = go.WithLogger(ctx, log.Default())
		if err := node.CompareAndSwap(ctx, "counter", new(int64), newVal); err != nil {
			// If CAS fails, try to update incrementally
			var temp int64
			tempVal := newNodeValue(readers + int64(req.Visitors))
			if err := node.RW(ctx, "counter", tempVal); err != nil {
				return nil, fmt.Errorf("update counter failed: %w", err)
			}
			temp = newNodeValue(tempVal)
			newVal = temp
		}

		// Response needs to include the new value for consistency checking
		res := totalRes{InReplyTo: req.MsgID, VisitorsSoFar: int(newVal)}
		outBytes, err := json.Marshal(res)
		return outBytes, err
	})

	node.Handle("total", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req totalReq
		if err := json.Unmarshal(in, &req); err != nil {
			return nil, fmt.Errorf("unmarshal failed: %w", err)
		}

		var readers int64
		ctx = go.WithLogger(ctx, log.Default())
		readers, _ = node.RW(ctx, "counter", 0)

		res := totalRes{InReplyTo: req.MsgID, VisitorsSoFar: int(readers)}
		outBytes, err := json.Marshal(res)
		return outBytes, err
	})

	node.Handle("counted", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req countRes
		if err := json.Unmarshal(in, &req); err != nil {
			return nil, fmt.Errorf("unmarshal failed: %w", err)
		}

		// Reply is just an empty message or a response with in_reply_to
		res := struct{}{}
		outBytes, _ := json.Marshal(res)
		return outBytes, nil
	})

	node.Handle("Send", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req struct {
			Dest   string `json:"dest"`
			Message []byte `json:"message"`
		}
		if err := json.Unmarshal(in, &req); err != nil {
			return nil, fmt.Errorf("unmarshal failed: %w", err)
		}

		outBytes, _ := node.Send(ctx, req.Dest, req.Message)
		return outBytes, nil
	})

	node.Handle("RPC", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req struct {
			Dest     string        `json:"dest"`
			Message  json.RawMessage `json:"message"`
			Callback int           `json:"callback"`
		}
		if err := json.Unmarshal(in, &req); err != nil {
			return nil, fmt.Errorf("unmarshal failed: %w", err)
		}

		msg := req.Message
		outBytes, _ := node.RPC(ctx, req.Dest, msg, req.Callback)
		return outBytes, nil
	})

	node.Handle("init", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req struct{}
		json.Unmarshal(in, &req)

		var id string
		var nodeIDs []string
		var ids []int

		id, _, _ = node.Init(ctx)
		for _, n := range nodeIDs {
			var nid int
			json.Unmarshal([]byte(n), &nid)
			ids = append(ids, nid)
		}

		outBytes, _ := json.Marshal(id)
		return outBytes, nil
	})

	node.Handle("Run", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req struct{}
		json.Unmarshal(in, &req)

		// Start the sequence number service
		ctx = go.WithLogger(ctx, log.Default())
		if _, err := node.SeqKV(ctx); err != nil {
			log.Printf("SeqKV failed: %v", err)
		}

		// Run the loop
		node.Run()
		return outBytes, err
	})

	var readers int64
	reader := go.NewSequenceNumber()
	ctx := go.WithLogger(ctx, log.Default())

	node.Handle("RW", func(c context.Context, key string, op uint8, val interface{}) (int64, error) {
		if val == nil {
			val = 0
		}
		return node.RW(c, key, 0) // Using the RW operation directly
	})

	node.Handle("Counter", func(ctx context.Context, in []byte) (out []byte, err error) {
		var req struct {
			Operation string `json:"operation"`
			Value     int64  `json:"value,omitempty"`
			Increment bool   `json:"increment,omitempty"`
		}

		if err := json.Unmarshal(in, &req); err != nil {
			return nil, fmt.Errorf("unmarshal failed: %w", err)
		}

		switch req.Operation {
		case "inc":
			var current int64
			current, err = node.RW(ctx, "counter", 0)
			if err != nil {
				return nil, fmt.Errorf("read counter failed: %w", err)
			}
			current += req.Value
			outBytes, _ := json.Marshal(map[string]interface{}{"value": current})
			return outBytes, nil

		case "get":
			current, err = node.RW(ctx, "counter", 0)
			if err != nil {
				return nil, fmt.Errorf("read counter failed: %w", err)
			}
			outBytes, _ := json.Marshal(map[string]interface{}{"value": current})
			return outBytes, nil

		case "set":
			newVal := req.Value
			ctx = go.WithLogger(ctx, log.Default())
			if _, err := node.CompareAndSwap(ctx, "counter", new(int64), newVal); err != nil {
				log.Printf("CAS failed for counter: %v", err)
				var temp int64
				tempVal := newNodeValue(current + req.Value)
				if err := node.RW(ctx, "counter", tempVal); err != nil {
					return nil, fmt.Errorf("set counter failed: %w", err)
				}
			}
			outBytes, _ := json.Marshal(map[string]interface{}{"value": current + req.Value})
			return outBytes, nil

		default:
			outBytes, _ := json.Marshal(map[string]interface{}{})
			return outBytes, nil
		}
	})
}

func newNodeValue(current int64) int64 {
	return current
}

